export interface QuoteResult {
  ok: boolean;
  error?: string;
  total?: number;
  policy?: string;
  line?: string;
}

interface CategorySpec {
  maxNights: number;
  maxGuests: number;
  base: number;
  highTip: number;
  minNights?: number;
  extra?: (guests: number) => number;
}

// One row per category; the per-category numbers replace the three duplicated
// validation ranges, rates, and surcharges that the old branches repeated.
const CATEGORIES: Record<string, CategorySpec> = {
  standard: { maxNights: 14, maxGuests: 2, base: 80, highTip: 30 },
  suite: { maxNights: 21, maxGuests: 4, base: 150, highTip: 60, extra: (g) => (g > 2 ? 25 : 0) },
  villa: { maxNights: 28, maxGuests: 8, base: 300, highTip: 120, minNights: 3, extra: () => 500 },
};

export function quoteBooking(raw: unknown): QuoteResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed request" };
  }
  const req = raw as Record<string, unknown>;
  const years = req.loyaltyYears as number;
  if (!Number.isInteger(years) || years < 0) {
    return { ok: false, error: "bad loyalty" };
  }

  const spec = CATEGORIES[req.category as string];
  if (!spec) {
    return { ok: false, error: "unknown category" };
  }

  const nights = req.nights as number;
  const guests = req.guests as number;

  if (!Number.isInteger(nights) || nights < 1 || nights > spec.maxNights) {
    return { ok: false, error: "bad nights" };
  }
  if (spec.minNights && nights < spec.minNights) {
    return { ok: false, error: "villa minimum stay" };
  }
  if (!Number.isInteger(guests) || guests < 1 || guests > spec.maxGuests) {
    return { ok: false, error: "bad guests" };
  }
  if (req.season !== "low" && req.season !== "high") {
    return { ok: false, error: "bad season" };
  }

  const privileged = years >= 3 || req.coupon === "VIP";
  let total = spec.base * nights;
  if (req.season === "high") {
    total += spec.highTip * nights;
  }
  if (privileged) {
    total -= Math.floor(total / 10);
  }
  if (spec.extra) {
    total += spec.extra(guests);
  }

  const policy = privileged ? "flex" : "strict";
  const line = String(req.category) + ":" + nights + "n:" + total + ":" + policy;
  return { ok: true, total, policy, line };
}

